def keep_recording_times(apps, schema_editor):
    """The recording times already set move to the settings of their file."""
    VideoRecordingTime = apps.get_model("dashboard", "VideoRecordingTime")
    SourceSettings = apps.get_model("dashboard", "SourceSettings")
    for row in VideoRecordingTime.objects.all():
        SourceSettings.objects.update_or_create(source_key=f"file:{row.file_name}",
                                                defaults={"recorded_at": row.recorded_at})


def drop_recording_time_permission(apps, schema_editor):
    """Setting the recording time is part of the video settings menu now, which anyone with the live view
    may use."""
    Permission = apps.get_model("auth", "Permission")
    Permission.objects.filter(content_type__app_label="dashboard", codename="set_recording_time").delete()


